import { passageDirection } from './dungeon-directions.js';
import { renderSpatialCommit } from './spatial-controls.js';
import { renderAreaScene } from './area-scenes.js';
import { rpgView } from './rpg-depth-v27.js';
import { renderAvatar } from './avatar.js';
export function depthPanel(s,ui,section='all'){
 const v=rpgView(s);if(!v||s.age<18)return '';const {e,actionCards}=ui;
 const actions=v.actions.filter(a=>!a.id.startsWith('rpg_move_')&&!a.id.startsWith('rpg_room_')&&!a.id.startsWith('rpg_boss_'));
 const rows=[];
 if(v.project)rows.push(`<section class="panel depth-project"><h2>A commitment in progress</h2><p>${e(v.project.id.replaceAll('_',' '))} · ${v.project.completedDays}/${v.project.totalDays} actual days kept.</p>${actionCards(actions.filter(a=>['rpg_continue','rpg_cancel'].includes(a.id)))}</section>`);
 if(['all','companions'].includes(section))rows.push(`<details class="depth-disclosure" data-disclosure="rpg-companions"><summary>Your circle <span>${v.companions.filter(c=>c.recruited).length} companions</span></summary><div class="depth-circle">${v.companions.map(c=>`<article>${renderAvatar(c,{size:'small',age:c.age})}<div><strong>${e(c.name)}</strong><p>${e(c.goal)}</p><span class="small-copy">${e(c.status)} · Trust ${Math.round(c.trust)} · Respect ${Math.round(c.respect)} · Fear ${Math.round(c.fear)} · ${c.stage}/5 chapters</span></div></article>`).join('')}</div>${actionCards(actions.filter(a=>/rpg_(companion_|meet_|expand_circle)/.test(a.id)))}</details>`);
 if(['all','stories'].includes(section)){
  rows.push(`<details class="depth-disclosure" data-disclosure="rpg-regional"><summary>Stories of this country <span>${v.arcs.filter(a=>a.status==='completed').length}/6 accounts</span></summary>${v.arcs.map(a=>`<p><strong>${e(a.title)}</strong> · ${a.chapter}/5 chapters · ${e(a.status)}</p>`).join('')}${actionCards(actions.filter(a=>/rpg_(regional_|relocate_)/.test(a.id)))}</details>`);
 }
 if(['all','factions'].includes(section)){
  rows.push(`<details class="depth-disclosure" data-disclosure="rpg-factions"><summary>Factions &amp; working agreements <span>${v.factions.length} known</span></summary>${v.factions.map(a=>`<p>${e(v.factionCatalog.find(d=>d.id===a.id)?.name)} · ${a.rank}/3 agreements</p>`).join('')}${actionCards(actions.filter(a=>/rpg_(join_|faction_)/.test(a.id)))}</details>`);
 }
 if(['all','adventure'].includes(section))rows.push(`<details class="depth-disclosure" data-disclosure="rpg-expeditions"><summary>Descent maps <span>${v.expeditions.filter(x=>x.completed).length} completed</span></summary><p class="small-copy">Six regional signature descents and twelve smaller sites. Side records, actual people and attended work offer alternatives to battle.</p>${actionCards(actions.filter(a=>a.id.startsWith('rpg_enter_')))}</details>`);
 if(['all','techniques'].includes(section))rows.push(`<details class="depth-disclosure" data-disclosure="rpg-techniques"><summary>Earned techniques <span>${v.trainedTechniques.length}/24 learned</span></summary><p>${e(v.trainedTechniques.map(id=>v.techniques.find(t=>t.id===id)?.name).join(' · '))||'Learn a calling, practice its skills, then attend advanced training.'}</p>${actionCards(actions.filter(a=>/^rpg_(train|practice)_/.test(a.id)||a.id.startsWith('rpg_practice_')))}</details>`);
 if(['all','stories'].includes(section)&&v.services.length)rows.push(`<details class="depth-disclosure" data-disclosure="rpg-services"><summary>The doors your stories opened <span>${v.services.length} recorded</span></summary>${actionCards(actions.filter(a=>a.id.startsWith('rpg_service_')))||'<p class="small-copy">Return to a surviving source location to use a recorded service.</p>'}</details>`);
 return rows.join('');
}
export function depthDungeonPanel(s,ui){
 const x=s.rpg?.expedition;if(!x)return '';const {e,actionCards}=ui,v=rpgView(s),current=x.rooms.find(r=>r.id===x.roomId),known=x.rooms.filter(r=>r.visited||current.neighbors.includes(r.id));
 const point=r=>[62+r.x*110,62+r.y*112],mapWidth=Math.max(480,...x.rooms.map(r=>point(r)[0]+65)),mapHeight=Math.max(280,...x.rooms.map(r=>point(r)[1]+85)),ids=new Set(known.map(r=>r.id));
 const edges=known.flatMap(r=>r.visited?r.neighbors.filter(id=>ids.has(id)&&(r.id<id||!known.find(n=>n.id===id).visited)).map(id=>{const b=x.rooms.find(r=>r.id===id),a=point(r),p=point(b);return `<path d="M${a.join(' ')}L${p.join(' ')}"/>`;}):[]).join('');
 const label=(text,p)=>{const lines=[];for(const word of text.split(/\s+/)){const last=lines.at(-1);if(last&&last.length+word.length+1<=17)lines[lines.length-1]+=' '+word;else lines.push(word);}return `<text x="${p[0]}" y="${p[1]+34}" text-anchor="middle" font-size="11" fill="#292722" stroke="none">${lines.map((line,i)=>`<tspan x="${p[0]}" dy="${i?11:0}">${e(line)}</tspan>`).join('')}</text>`;};
 const nodes=known.map(r=>{const p=point(r);return `<g class="${r.id===x.roomId?'current':''}" data-op="dungeon-select" data-id="${e(r.id)}" role="button" tabindex="0" aria-pressed="${(ui.selectedDungeonRoom||x.roomId)===r.id}" aria-describedby="spatial-map-help" aria-label="${e(r.visited?r.title:passageDirection(s.seed,x.id,current,r))}"><circle cx="${p[0]}" cy="${p[1]}" r="16"/><text x="${p[0]}" y="${p[1]+5}" text-anchor="middle" fill="#292722" stroke="none">${r.id===x.roomId?'†':r.resolved?'✓':r.visited?'◇':'?'}</text>${label(r.visited?r.title:passageDirection(s.seed,x.id,current,r),p)}</g>`;}).join('');
 return `<div class="depth-dungeon exploration-workspace"><section class="depth-dungeon-map"><div class="section-heading"><div><span class="eyebrow">THE DESCENT</span><h2>${e(x.title)}</h2></div><span class="badge">${x.rooms.filter(r=>r.visited).length}/${x.rooms.length} rooms</span></div><svg viewBox="0 0 ${mapWidth} ${mapHeight}" role="group" aria-label="Discovered dungeon rooms"><rect width="${mapWidth}" height="${mapHeight}" fill="#b6b0a2"/><image href="./art/parchment-v22.png" width="${mapWidth}" height="${mapHeight}" opacity=".16"/><g fill="none" stroke="#55524b" stroke-width="2">${edges}</g><g fill="#d2cabb" stroke="#55524b">${nodes}</g></svg><p id="spatial-map-help" class="small-copy">Click, Enter or Space to inspect. Choose Confirm to move, or double click an available neighboring room. The chart keeps unknown rooms unnamed. Side stores, records and resolved hazards persist when you leave.</p></section><aside class="panel depth-dungeon-actions">${renderAreaScene(s,ui,{dungeon:{room:{title:current.title}}})}${ui.selectedDungeonRoom?`<h2 id="spatial-selection-title" aria-describedby="spatial-selection-details">${e(known.find(r=>r.id===ui.selectedDungeonRoom)?.visited?known.find(r=>r.id===ui.selectedDungeonRoom).title:known.find(r=>r.id===ui.selectedDungeonRoom)?passageDirection(s.seed,x.id,current,known.find(r=>r.id===ui.selectedDungeonRoom)):'No visible doorway')}</h2>${known.some(r=>r.id===ui.selectedDungeonRoom)?renderSpatialCommit(s,'rpg',ui.selectedDungeonRoom,v.actions,ui):''}`:''}<h2>${e(current.title)}</h2>${actionCards(v.actions)}${x.completed?'<p>The completed service remains in the world.</p>':''}</aside></div>`;
}
export function relicPanel(s,ui){const {e,actionCards}=ui,properties=s.rpg?.properties||[],active=properties.filter(p=>p.soldDay===null&&p.returnedDay===null);return `<section class="panel"><h2>Relics &amp; claims</h2><p class="small-copy">Unique property retains its source, owner and consequences.</p>${active.map(p=>`<article><strong>${e(p.label)}</strong><p>Acquired on day ${p.acquiredDay}${p.pursuitUntil>s.day&&p.pursuitDefeatedDay===null?' · The original owner is pursuing it.':''}</p></article>`).join('')||'<p>No unique property is carried.</p>'}${actionCards(rpgView(s)?.actions.filter(a=>a.id.startsWith('rpg_property_'))||[])}${properties.some(p=>p.soldDay!==null||p.returnedDay!==null)?`<details><summary>Transferred property</summary>${properties.filter(p=>p.soldDay!==null||p.returnedDay!==null).map(p=>`<p>${e(p.label)} · ${p.returnedDay!==null?'returned':'sold'} on day ${p.returnedDay??p.soldDay}</p>`).join('')}</details>`:''}</section>`;}
